static void * platform_init ( struct nvkm_bios * bios , const char * name ) { struct nvkm_device * device = bios -> subdev . device ; struct pci_dev * pdev ; struct priv * priv ; int ret = - ENOMEM ; if ( device -> func -> pci ) { pdev = device -> func -> pci ( device ) -> pdev ; } else { return ERR_PTR ( - ENODEV ) ; } if ( ( priv = kmalloc ( sizeof ( * priv ) , GFP_KERNEL ) ) ) { priv -> size = pdev -> romlen ; if ( ret = - ENODEV , ( priv -> rom = ioremap ( pdev -> rom , pdev -> romlen ) ) ) { return priv ; } kfree ( priv ) ; } return ERR_PTR ( ret ) ; } 